  const tasks = data ? data : [];

  return (
    <div>
      <Grid container alignItems="center">
        <Grid item>
          Last updated: {timeStamp.format("YYYY-MM-DD HH:mm:ss")}
        </Grid>
      </Grid>
      <TaskTable
        tasks={tasks}
        jobId={jobId}
        actorId={actorId}
        {...taskTableProps}
      />
    </div>
  );
};

